using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using RoadGunner;using RoadGunner.Editor;
public static class FinalizeGreenwood{public static string Main(){
 if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play first");if(SceneManager.GetActiveScene().path!=AstraZone01Builder.ScenePath)throw new InvalidOperationException("Open Greenwood");var l=RoadGunnerLevelAuthoring.Current;l.session.vehicle.transform.SetPositionAndRotation(l.playerSpawn.position,l.playerSpawn.rotation);if(PrefabUtility.IsPartOfPrefabInstance(l.session.vehicle.transform))PrefabUtility.RecordPrefabInstancePropertyModifications(l.session.vehicle.transform);
 var backup=AstraZone01Builder.Report+"/EditorBuildSettings.before.asset";if(!File.Exists(backup))File.Copy("ProjectSettings/EditorBuildSettings.asset",backup);
 EditorBuildSettings.scenes=EditorBuildSettings.scenes.Where(s=>s.path!=AstraZone01Builder.ScenePath).Prepend(new EditorBuildSettingsScene(AstraZone01Builder.ScenePath,true)).ToArray();
 RoadGunnerLevelAuthoring.Save(l,false);
 foreach(string filename in new[]{"GreenwoodOverview.png","GreenwoodEntry.png","GreenwoodOverviewFinal.png","Greenwood-entry.png","Greenwood-southwest.png","Greenwood-sanctuary.png","Greenwood-crossroads.png","Greenwood-west.png","Greenwood-north.png","Greenwood-northeast.png","Greenwood-tree.png","Greenwood-sealed.png","Greenwood-westgate.png"}){
  string src="Assets/"+filename;if(!File.Exists(src))continue;File.Copy(src,AstraZone01Builder.Report+"/"+filename,true);if(!AssetDatabase.DeleteAsset(src)){File.Delete(src);if(File.Exists(src+".meta"))File.Delete(src+".meta");}
 }
 var view=SceneView.lastActiveSceneView;if(view){view.orthographic=true;view.LookAtDirect(AstraZone01Builder.World(-4,9),Quaternion.Euler(57,45,0),81);view.Repaint();}Selection.activeObject=l.gameObject;
 var result=AstraZone01Builder.Inspect();File.WriteAllText(AstraZone01Builder.Report+"/SavedState.txt","Scene="+SceneManager.GetActiveScene().path+"\nDirty="+SceneManager.GetActiveScene().isDirty+"\nBuild scene 0="+EditorBuildSettings.scenes[0].path+"\nSanctuary="+(l.decorationRoot.GetComponentInChildren<GreenwoodSanctuary>(true)!=null)+"\n");return result;
}}